import{_ as a,o as e,c as o,ag as t}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年8月23日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-23.md","filePath":"science-log/src/reconstructed/2026-08-23.md"}'),n={name:"science-log/src/reconstructed/2026-08-23.md"};function s(i,r,g,l,u,c){return e(),o("div",null,[...r[0]||(r[0]=[t('<h1 id="🔬-科学快报-2026年8月23日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月23日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月23日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月23日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-08-23 为<strong>周日</strong>，Nature（0028-0836）/ Science 系（10.1126）/ PNAS（0027-8424）的 CrossRef 当日命中均为 <strong>0 条</strong>（期刊周末不刊出，08-22 周六同样为 0）。故科学 5 篇取自<strong>最近的刊出窗口 2026-08-21 ~ 2026-08-24</strong>（Science Advances 2026-08-21 三篇 + PNAS 2026-08-24 两篇），并逐条标注实际出版日；AI 5 篇取自当日 arXiv cs.AI 提交（<code>submittedDate</code> 命中 30 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608230000 TO 202608232359]</code>（cs.AI）｜ 重建日：2026-11-06</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌌-钙铝包体的古地磁记录-太阳系最早期星云磁场约-150–600-μt" tabindex="-1">🌌 钙铝包体的古地磁记录：太阳系最早期星云磁场约 150–600 μT <a class="header-anchor" href="#🌌-钙铝包体的古地磁记录-太阳系最早期星云磁场约-150–600-μt" aria-label="Permalink to &quot;🌌 钙铝包体的古地磁记录：太阳系最早期星云磁场约 150–600 μT&quot;">​</a></h3><p><strong>Paleomagnetic evidence for a nebular magnetic field from calcium-aluminum-rich inclusions</strong><em>PNAS (2026-08-24)</em></p><p>行星形成的最初阶段被认为发生在原行星盘（PPD）中，而高冷凝温度固体——钙铝包体（CAI，已知最古老的太阳系固体）正记录着那时的环境。Cauê S. Borlina、Benjamin P. Weiss 等（合作者含清华大学 Xue-Ning Bai、剑桥大学 Richard J. Harrison）对 CAI 做古地磁测量，得到约 <strong>150–600 微特斯拉</strong>的星云磁场强度。该强度与&quot;磁场在驱动盘吸积中扮演关键角色、同时把极内盘加热到 10³ K&quot;的图景一致。这把&quot;最早期吸积由磁场还是引力主导&quot;的问题推向了磁场一侧。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2521660123" target="_blank" rel="noreferrer">10.1073/pnas.2521660123</a></p><h3 id="🧬-七个冷冻电镜结构拆解-cas13d-的靶标区分与激活机制" tabindex="-1">🧬 七个冷冻电镜结构拆解 Cas13d 的靶标区分与激活机制 <a class="header-anchor" href="#🧬-七个冷冻电镜结构拆解-cas13d-的靶标区分与激活机制" aria-label="Permalink to &quot;🧬 七个冷冻电镜结构拆解 Cas13d 的靶标区分与激活机制&quot;">​</a></h3><p><strong>Structural basis for target discrimination and activation by Cas13d</strong><em>Science Advances (2026-08-21)</em></p><p>Cas13d 已广泛用于 RNA 敲低，但对近缘序列的脱靶切割阻碍了其推广。Chia-Wei Chou、Rick Russell、Ilya J. Finkelstein 等（得克萨斯大学奥斯汀分校）解析了野生型 Cas13d 与匹配／错配靶标复合物的 <strong>7 个冷冻电镜结构</strong>，捕获活性态、中间态与非活性态，给出完整的激活机制。靶 RNA 结合后 crRNA 发生显著构象变化，Helical-1 结构域从与 N 端结构域锚定的状态切换到稳定 RNA 双链的变构构象。定量动力学显示：<strong>单个近端错配不改变结合速率常数，却把 Cas13d 困在非活性态、彻底关闭核酸酶活性</strong>；研究还识别出 HEPN 结构域中调控活性的活性位点环。这为设计高保真 Cas13d 变体提供了结构依据。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aec4221" target="_blank" rel="noreferrer">10.1126/sciadv.aec4221</a></p><h3 id="🧮-动物染色体演化的-拓扑混合-与不可逆性" tabindex="-1">🧮 动物染色体演化的&quot;拓扑混合&quot;与不可逆性 <a class="header-anchor" href="#🧮-动物染色体演化的-拓扑混合-与不可逆性" aria-label="Permalink to &quot;🧮 动物染色体演化的&quot;拓扑混合&quot;与不可逆性&quot;">​</a></h3><p><strong>Topological mixing and irreversibility in animal chromosome evolution</strong><em>Science Advances (2026-08-21)</em></p><p>动物染色体同源性可跨越数亿年保持，但融合与易位的频率、节奏和影响长期不清。Darrin T. Schultz、Arno Blümel、Dalila Destanović、Fatih Sarigol、Oleg Simakov（维也纳大学）构建了泛动物基因组同源性的<strong>多尺度流形表示</strong>，比较 19 个门、4454 个物种的 <strong>5821 个染色体级基因组</strong>，提出&quot;演化基因组拓扑&quot;框架。结果显示：29 个祖先连锁群的 <strong>406 种两两融合</strong>都已在后生动物多样性中被采样到，但染色体内部的组合潜力远未被穷尽。由染色体整合、解离与&quot;融合伴混合&quot;造成的<strong>不可逆</strong>变化把各支系定位在基因组结构空间的不同区域，混合状态的渐进累积形成棘轮。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.adz5561" target="_blank" rel="noreferrer">10.1126/sciadv.adz5561</a></p><h3 id="💡-光子集成电路上的端到端全光-在感内计算" tabindex="-1">💡 光子集成电路上的端到端全光&quot;在感内计算&quot; <a class="header-anchor" href="#💡-光子集成电路上的端到端全光-在感内计算" aria-label="Permalink to &quot;💡 光子集成电路上的端到端全光&quot;在感内计算&quot;&quot;">​</a></h3><p><strong>End-to-end all-optical in-sensor computing system using photonic integrated circuits</strong><em>Science Advances (2026-08-21)</em></p><p>传统光子传感系统依赖顺序波长扫描与大量电子后处理，导致数据冗余大、延迟高、能耗高。Zian Xiao、Zhihao Ren、Bowei Dong、Chengkuo Lee 等（新加坡国立大学）把<strong>光子波导传感器与微环权重库集成在单芯片</strong>上完成线性运算，非线性激活由掺铒光纤放大器（EDFA）实现，构成端到端全光在感内计算系统。借助光谱压缩，系统在<strong>光域实时计算达 6 bit 精度</strong>，在 <strong>27 类液体混合物上分类准确率 94.2%</strong>，并能直接做混合物浓度预测。相对常规方案，它把&quot;传感—计算&quot;之间的电子往返环节去掉，显著降低冗余、延迟与能耗。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aef8657" target="_blank" rel="noreferrer">10.1126/sciadv.aef8657</a></p><h3 id="🔥-gsdme-孔道的冷冻电镜结构与-s-棕榈酰化调控" tabindex="-1">🔥 GSDME 孔道的冷冻电镜结构与 S-棕榈酰化调控 <a class="header-anchor" href="#🔥-gsdme-孔道的冷冻电镜结构与-s-棕榈酰化调控" aria-label="Permalink to &quot;🔥 GSDME 孔道的冷冻电镜结构与 S-棕榈酰化调控&quot;">​</a></h3><p><strong>Structural basis of GSDME pore formation and its regulation by S-palmitoylation</strong><em>PNAS (2026-08-24)</em></p><p>焦亡由 gasdermin 家族介导；GSDME 是凋亡蛋白酶 caspase-3 的底物，能把凋亡&quot;切换&quot;为焦亡，在抗肿瘤免疫与化疗所致组织损伤中至关重要，但其成孔机制与翻译后修饰调控一直不明。Gang Du、Julian F. Ehrmann、Judy Lieberman、Hao Wu（哈佛医学院／波士顿儿童医院）用哺乳动物细胞表达的蛋白解析了人 GSDME N 端孔道 <strong>3.16 Å</strong> 的冷冻电镜结构。孔道主要以 <strong>28 聚体</strong>同源寡聚体组装，从自抑制态发生剧烈构象重排——每个单体的两个 β-发夹重折叠成跨膜 β-桶并形成酸性通道。研究还意外鉴定出<strong>内源性 S-棕榈酰化</strong>对成孔的调控。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614339123" target="_blank" rel="noreferrer">10.1073/pnas.2614339123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🤖-physical-agentic-ai-为-机器人班组-建立语义规划与执行之间的验证接口" tabindex="-1">🤖 Physical Agentic AI：为&quot;机器人班组&quot;建立语义规划与执行之间的验证接口 <a class="header-anchor" href="#🤖-physical-agentic-ai-为-机器人班组-建立语义规划与执行之间的验证接口" aria-label="Permalink to &quot;🤖 Physical Agentic AI：为&quot;机器人班组&quot;建立语义规划与执行之间的验证接口&quot;">​</a></h3><p><strong>Physical Agentic AI: An Architecture for Orchestrating a Robot Crew with LLMs</strong><em>arXiv cs.AI (2026-08-23)</em></p><p>Xinyuan Liu、Eren Sadikoglu、Riana Chatterjee、Ransalu Senanayake 提出 Physical Agentic AI 框架：每台机器人暴露一套<strong>类型化的可执行技能库</strong>，基础模型规划器把任务分解为阶段并指派&quot;机器人—技能&quot;配对。一个不直接执行动作的 Mission Planner 面向技能库、机器人状态、命名地点与工作流契约，而确定性的 Robot Orchestrator <strong>逐条验证并授权技能——每次只放行一条</strong>，执行前对照机器人能力、系统状态与流程约束。作者在无人机—无人地面车搜索派送任务上全部于 <strong>Gazebo 实时执行</strong>，并在人形—四足平台上验证。核心命题是：更丰富的具身信息能改善接地，但<strong>不能消除&quot;语义合理却物理不可行／时序错误／不安全&quot;的动作</strong>，必须靠架构层显式验证。</p><p>arXiv: <a href="https://arxiv.org/abs/2608.22657" target="_blank" rel="noreferrer">2608.22657</a></p><h3 id="🗺️-georisk-rag-把-地理有效性-与-语义相似-分开的选择性回答框架" tabindex="-1">🗺️ GeoRisk-RAG：把&quot;地理有效性&quot;与&quot;语义相似&quot;分开的选择性回答框架 <a class="header-anchor" href="#🗺️-georisk-rag-把-地理有效性-与-语义相似-分开的选择性回答框架" aria-label="Permalink to &quot;🗺️ GeoRisk-RAG：把&quot;地理有效性&quot;与&quot;语义相似&quot;分开的选择性回答框架&quot;">​</a></h3><p><strong>GeoRisk-RAG: A Hierarchy-Aware Risk Framework for Improving RAG Reliability through Selective Answering</strong><em>arXiv cs.AI (2026-08-23)</em></p><p>Meenu Ravi、Shailik Sarkar、Lulwah AlKulaib、Yordanos Tessema、Chang-Tien Lu（弗吉尼亚理工）指出：现有 RAG／知识图谱／强化学习方案擅长用语义相似度与忠实度衡量可靠性，却分不清&quot;语义相似&quot;与&quot;地理有效&quot;。在自然灾害管理中，镇／市／州的空间粒度直接决定决策有效性，一个市适用的答案未必能迁移到另一个市，此时**&quot;自信的错误&quot;比&quot;拒答&quot;风险更大**。GeoRisk-RAG 在生成答案前用基于<strong>有向无环图（DAG）的距离</strong>显式估计地理适用性，实现选择性回答。在自建的野火问答数据集上，它显著降低了位置依赖问题的虚假自信率。</p><p>arXiv: <a href="https://arxiv.org/abs/2608.22634" target="_blank" rel="noreferrer">2608.22634</a></p><h3 id="🧠-deepsage-面向结构化-cbt-咨询对话的-阶段感知-强化学习" tabindex="-1">🧠 DeepSAGE：面向结构化 CBT 咨询对话的&quot;阶段感知&quot;强化学习 <a class="header-anchor" href="#🧠-deepsage-面向结构化-cbt-咨询对话的-阶段感知-强化学习" aria-label="Permalink to &quot;🧠 DeepSAGE：面向结构化 CBT 咨询对话的&quot;阶段感知&quot;强化学习&quot;">​</a></h3><p><strong>DeepSAGE: Stage-Aware Reinforcement Learning for Structured CBT Counseling Dialogue</strong><em>arXiv cs.AI (2026-08-23)</em></p><p>Qi Zhang、Heajun An、Prakriti Dumaru、Sang Won Lee、Lifu Huang、Pamela J. Wisniewski 提出混合 LLM—深度强化学习框架 DeepSAGE，把认知行为疗法（CBT）首次会谈拆成 <strong>11 个带明确治疗目标的阶段</strong>：外部控制器判定阶段是否完成，DRL 模型选择<strong>治疗意图</strong>，再由 LLM 依据意图生成回应。与 6 种基于检索／提示／阶段／策略的替代方案对比，DeepSAGE 取得更高的模拟来访者参与度与开放度，并在<strong>阶段目标完成与对话效率之间取得最佳平衡</strong>；领域专家评审认为生成对话呈现合理的情感轨迹与可识别的 CBT 流程。局限在于评估主要依赖模拟来访者与模型指标。</p><p>arXiv: <a href="https://arxiv.org/abs/2608.22615" target="_blank" rel="noreferrer">2608.22615</a></p><h3 id="🧹-blade-双层低秩增广拉格朗日的-llm-遗忘方法" tabindex="-1">🧹 BLADE：双层低秩增广拉格朗日的 LLM 遗忘方法 <a class="header-anchor" href="#🧹-blade-双层低秩增广拉格朗日的-llm-遗忘方法" aria-label="Permalink to &quot;🧹 BLADE：双层低秩增广拉格朗日的 LLM 遗忘方法&quot;">​</a></h3><p><strong>BLADE: Bilevel Low-rank Augmented-Lagrangian Erasure for LLM Unlearning</strong><em>arXiv cs.AI (2026-08-23)</em></p><p>Md Toufikuzzaman、Ahmad Mousavi、Dongwon Lee 针对现有 LLM 遗忘方法的三个鲁棒性缺陷——无界遗忘损失损害模型连贯性、固定权重无法适应训练中&quot;保留难度&quot;漂移、单基准有效但扩展或重复应用即失效——提出约束式双层框架 BLADE，含三个机制：<strong>截断熵遗忘损失</strong>（token 达到足够不确定度后梯度<strong>恰好为零</strong>）、<strong>非对称增广拉格朗日</strong>（任何违反后永久棘轮式增强保留保护）、<strong>限制在 LoRA 适配器上的双层结构</strong>（每次遗忘步骤前修复保留集损伤）。综合得分较最强基线在 <strong>TOFU 提升 6%、MUSE Books 提升 9%、KnowUndo 提升 7%</strong>，并在 4× 规模与 MUSE News 上连续 4 次遗忘仍保持稳定，而最佳竞品完全崩溃。</p><p>arXiv: <a href="https://arxiv.org/abs/2608.22557" target="_blank" rel="noreferrer">2608.22557</a></p><h3 id="🧭-contramem-从-多模型轨迹对比-中自演化出的程序性记忆" tabindex="-1">🧭 CONTRAMEM：从&quot;多模型轨迹对比&quot;中自演化出的程序性记忆 <a class="header-anchor" href="#🧭-contramem-从-多模型轨迹对比-中自演化出的程序性记忆" aria-label="Permalink to &quot;🧭 CONTRAMEM：从&quot;多模型轨迹对比&quot;中自演化出的程序性记忆&quot;">​</a></h3><p><strong>CONTRAMEM: Learning Self-Evolving Procedural Memory from Contrasting Multi-Model Trajectories</strong><em>arXiv cs.AI (2026-08-23)</em></p><p>Zheyuan Deng 等提出 CONTRAMEM：一个<strong>免训练、来源灵活</strong>的自我演化程序性记忆框架，把同一任务的结果差异当作监督信号——正确性、效率、恢复能力与失败模式的差异暴露出与结果相关的程序性区分，被蒸馏成紧凑的<strong>应用级 Function Cards + 任务级 Skill Cards</strong>。记忆库通过<strong>局部整理</strong>演化，而非只追加或整库重写。在留出的 <strong>GAIA2/ARE</strong> 计算机使用任务上，三个来源模型目标的成功率从 <strong>26.2% 提升到 55.3%</strong>（GPT-5.5: 27.5→61.0；Claude Sonnet 4.6: 28.0→52.5；DeepSeek V4 Pro: 23.0→52.5），且同一记忆库可跨模型迁移。</p><p>arXiv: <a href="https://arxiv.org/abs/2608.22533" target="_blank" rel="noreferrer">2608.22533</a></p><blockquote><p>📅 日期：2026-08-23 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const p=a(n,[["render",s]]);export{d as __pageData,p as default};
